H.background();
const w = H.W, h = H.H;
// Bohr model of hydrogen: E_n = -13.6 / n^2  eV,  r_n = n^2 * a0.
const n = Math.round(P.level);          // principal quantum number 1..6
const Z = 1;                            // hydrogen
const E_n = -13.6 * Z * Z / (n * n);    // eV
const r_n = n * n;                      // in Bohr radii a0
// --- left: orbiting electron picture ---
const ox = w * 0.30, oy = h * 0.52;
// draw the allowed orbits (faint), highlight the current one
for (let k = 1; k <= 6; k++) {
  const rr = 18 + k * k * 4.2;
  H.circle(ox, oy, rr, { stroke: k === n ? H.colors.accent : H.colors.grid, width: k === n ? 2.5 : 1 });
}
// nucleus
H.circle(ox, oy, 9, { fill: H.colors.warn, stroke: H.colors.bg, width: 2 });
H.text("+", ox - 4, oy + 5, { color: H.colors.bg, size: 14, weight: 700 });
// electron orbiting on level n; angular speed falls with n (slower far out)
const rOrbit = 18 + n * n * 4.2;
const ang = t * (2.2 / (n * n)) * H.TAU * 0.5 + 0.4;
const ex = ox + rOrbit * Math.cos(ang);
const ey = oy + rOrbit * Math.sin(ang);
H.circle(ex, ey, 7, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
H.text("e-", ex + 8, ey - 6, { color: H.colors.accent, size: 12 });
H.text("orbit radius  r = n²·a₀ = " + r_n + "·a₀", ox - 90, oy + 150, { color: H.colors.sub, size: 12 });
// --- right: energy-level ladder ---
const lx = w * 0.66, lw = w * 0.26;
const topY = h * 0.16, botY = h * 0.80;
// map E from -13.6..0 eV onto botY..topY
function Ey(E) { return H.map(E, -13.6, 0, botY, topY); }
H.line(lx, topY, lx, botY, { color: H.colors.axis, width: 1.5 });
H.text("E (eV)", lx - 6, topY - 10, { color: H.colors.sub, size: 12, align: "right" });
for (let k = 1; k <= 6; k++) {
  const Ek = -13.6 / (k * k);
  const yk = Ey(Ek);
  const isCur = k === n;
  H.line(lx, yk, lx + lw, yk, { color: isCur ? H.colors.accent : H.colors.grid, width: isCur ? 3 : 1.5 });
  H.text("n=" + k, lx + lw + 6, yk + 4, { color: isCur ? H.colors.accent : H.colors.sub, size: 12 });
  H.text(Ek.toFixed(2), lx - 8, yk + 4, { color: isCur ? H.colors.ink : H.colors.sub, size: 11, align: "right" });
}
// ionization level (E=0) and the electron marker pulsing on its level
H.line(lx, Ey(0), lx + lw, Ey(0), { color: H.colors.good, width: 1.5, dash: [4, 4] });
H.text("n=∞  (ionized, E=0)", lx + lw + 6, Ey(0) + 4, { color: H.colors.good, size: 11 });
const pulse = 6 + 1.5 * Math.sin(t * 4);
H.circle(lx + lw * 0.5, Ey(E_n), pulse, { fill: H.colors.accent });
// title + readouts
H.text("Bohr model:  Eₙ = −13.6 / n²  eV", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("n = " + n + "    Eₙ = " + E_n.toFixed(2) + " eV", 24, 56, { color: H.colors.accent, size: 14, weight: 700 });
H.text("ionization energy from this level = " + (0 - E_n).toFixed(2) + " eV", 24, 78, { color: H.colors.sub, size: 13 });
H.text("levels crowd toward 0 as n grows — energy is QUANTIZED", 24, h - 18, { color: H.colors.sub, size: 12 });
